$lfsworld_teams$::jsonb) AS source (
    lfsworld_id BIGINT, owner_username TEXT, name TEXT, tag TEXT,
    website_url TEXT, description TEXT, tags JSONB, accepts_applications BOOLEAN,
    updated_timestamp BIGINT, members JSONB
);

-- Preserve existing profiles; missing accounts are unauthenticated placeholders.
WITH usernames AS (
    SELECT owner_username AS username FROM lfsworld_team_import
    UNION ALL
    SELECT jsonb_array_elements_text(members) FROM lfsworld_team_import
)
INSERT INTO player (lfs_username, display_name)
SELECT DISTINCT ON (lower(username)) username, username
FROM usernames
ORDER BY lower(username), username COLLATE "C"
ON CONFLICT (lower(lfs_username)) DO NOTHING;

INSERT INTO team (
    lfsworld_id, name, tag, website_url, description, tags,
    accepts_applications, status, lfsworld_updated_at
)
SELECT lfsworld_id, name, tag, website_url, description, tags,
    accepts_applications, 'active', to_timestamp(updated_timestamp::double precision)
FROM lfsworld_team_import
ORDER BY lfsworld_id;

-- Ownership is a membership role, including owners missing from the source member list.
WITH memberships AS (
    SELECT lfsworld_id, owner_username, owner_username AS username
    FROM lfsworld_team_import
    UNION ALL
    SELECT lfsworld_id, owner_username, jsonb_array_elements_text(members)
    FROM lfsworld_team_import
)
INSERT INTO team_member (team_id, player_id, role)
SELECT DISTINCT team.id, player.id,
    CASE WHEN lower(memberships.owner_username) = lower(player.lfs_username)
        THEN 'owner' ELSE 'member' END
FROM memberships
JOIN team USING (lfsworld_id)
JOIN player ON lower(player.lfs_username) = lower(memberships.username);
